package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sort"
)

func digest(text string) string {
	sum := sha256.Sum256([]byte(text))
	return hex.EncodeToString(sum[:])
}
func main() {
	files := map[string]string{"a.txt": "alpha", "b.txt": "changed"}
	manifest := map[string]string{"a.txt": digest("alpha"), "b.txt": digest("beta")}
	names := []string{}
	for name := range manifest {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		data, exists := files[name]
		fmt.Printf("%s exists=%t match=%t\n", name, exists, exists && digest(data) == manifest[name])
	}
	_, err := hex.DecodeString("xyz")
	fmt.Printf("bad-manifest=%t\n", err != nil)
}

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"fmt"
)

func tag(key, message []byte) []byte {
	mac := hmac.New(sha256.New, key)
	mac.Write(message)
	return mac.Sum(nil)
}
func verify(key, message, want []byte) bool { return hmac.Equal(tag(key, message), want) }
func main() {
	key := []byte("lesson-only-shared-key")
	message := []byte("invoice:7:1250")
	signature := tag(key, message)
	fmt.Printf("tag-bytes=%d\nvalid=%t\ntampered=%t\nwrong-key=%t\n", len(signature), verify(key, message, signature), verify(key, []byte("invoice:7:9250"), signature), verify([]byte("other-key"), message, signature))
}

