import (
	"crypto/subtle"
	"encoding/hex"
	"fmt"
)

func valid(input string, want []byte) bool {
	decoded, err := hex.DecodeString(input)
	if err != nil || len(decoded) != len(want) || len(want) != 4 {
		return false
	}
	return subtle.ConstantTimeCompare(decoded, want) == 1
}
func main() {
	token := []byte{0x21, 0x4a, 0xb0, 0x09}
	for _, input := range []string{"214ab009", "214ab008", "21", "zzzzzzzz"} {
		fmt.Printf("%s=%t\n", input, valid(input, token))
	}
}

package main

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"fmt"
)

func main() {
	key := make([]byte, 32)
	if _, err := rand.Read(key); err != nil {
		panic(err)
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		panic(err)
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		panic(err)
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		panic(err)
	}
	message := []byte("offline report")
	aad := []byte("report:v1")
	sealed := gcm.Seal(nil, nonce, message, aad)
	plain, err := gcm.Open(nil, nonce, sealed, aad)
	fmt.Printf("roundtrip=%t\n", err == nil && bytes.Equal(plain, message))
	sealed[len(sealed)-1] ^= 1
	_, err = gcm.Open(nil, nonce, sealed, aad)
	fmt.Printf("tamper-rejected=%t\n", err != nil)
}

package main

import (
	"crypto/ed25519"
	"crypto/rand"
	"fmt"
)

func main() {
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}
	manifest := []byte("files=2;version=3")
	signature := ed25519.Sign(private, manifest)
	fmt.Printf("signature-bytes=%d\nvalid=%t\nchanged=%t\n", len(signature), ed25519.Verify(public, manifest, signature), ed25519.Verify(public, []byte("files=9;version=3"), signature))
	signature[0] ^= 1
	fmt.Printf("bad-signature=%t\n", ed25519.Verify(public, manifest, signature))
}

package main

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"fmt"
)

func main() {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		panic(err)
	}
	digest := sha256.Sum256([]byte("release:42"))
	signature, err := ecdsa.SignASN1(rand.Reader, key, digest[:])
	if err != nil {
		panic(err)
	}
	changed := sha256.Sum256([]byte("release:43"))
	fmt.Printf("valid=%t\nchanged=%t\nmalformed=%t\n", ecdsa.VerifyASN1(&key.PublicKey, digest[:], signature), ecdsa.VerifyASN1(&key.PublicKey, changed[:], signature), ecdsa.VerifyASN1(&key.PublicKey, digest[:], []byte{1, 2, 3}))
}

package main

import (
	"bytes"
	"crypto/ecdh"
	"crypto/rand"
	"fmt"
)

func main() {
	curve := ecdh.P256()
	alice, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}
	bob, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}
	first, err := alice.ECDH(bob.PublicKey())
	if err != nil {
		panic(err)
	}
	second, err := bob.ECDH(alice.PublicKey())
	if err != nil {
		panic(err)
	}
	fmt.Printf("same=%t\nsecret-bytes=%d\n", bytes.Equal(first, second), len(first))
	_, err = curve.NewPublicKey([]byte{1, 2, 3})
	fmt.Printf("bad-key-rejected=%t\n", err != nil)
}

package main

import (
	"bytes"
	"crypto/ed25519"
	"crypto/rand"
	"crypto/x509"
	"encoding/pem"
	"fmt"
)

func main() {
	public, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}
	der, err := x509.MarshalPKIXPublicKey(public)
	if err != nil {
		panic(err)
	}
	encoded := pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der})
	block, rest := pem.Decode(encoded)
	if block == nil || block.Type != "PUBLIC KEY" || len(rest) != 0 {
		panic("unexpected PEM")
	}
	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		panic(err)
	}
	restored, ok := parsed.(ed25519.PublicKey)
	fmt.Printf("block=%s\nroundtrip=%t\n", block.Type, ok && bytes.Equal(public, restored))
	bad, _ := pem.Decode([]byte("not a PEM block"))
	fmt.Printf("invalid-rejected=%t\n", bad == nil)
}

package main

import (
	"fmt"
	"hash/crc32"
)

func main() {
	chunks := [][]byte{[]byte("sensor:"), []byte("north:"), []byte("21.5")}
	rolling := uint32(0)
	all := []byte{}
	for _, chunk := range chunks {
		rolling = crc32.Update(rolling, crc32.IEEETable, chunk)
		all = append(all, chunk...)
	}
	fmt.Printf("same=%t\n", rolling == crc32.ChecksumIEEE(all))
	all[len(all)-1] ^= 1
	fmt.Printf("changed=%t\n", rolling != crc32.ChecksumIEEE(all))
	fmt.Printf("empty=%d\n", crc32.ChecksumIEEE(nil))
}

package main

import (
	"crypto/sha256"
	"crypto/sha512"
	"fmt"
	"io"
	"strings"
)

func main() {
	input := "alpha\nbeta\n"
	small := sha256.New()
	large := sha512.New()
	copied, err := io.Copy(io.MultiWriter(small, large), strings.NewReader(input))
	if err != nil {
		panic(err)
	}
	expected := sha256.Sum256([]byte(input))
	fmt.Printf("bytes=%d\nlengths=%d,%d\nsha256-match=%t\n", copied, len(small.Sum(nil)), len(large.Sum(nil)), fmt.Sprintf("%x", small.Sum(nil)) == fmt.Sprintf("%x", expected))
}
